import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_layernorm_cuda_src = r"""
   #include <torch/extension.h>
   #include <cuda.h>
   #include <cuda_runtime.h>
   #include <ATen/cuda/CUDAContext.h>
   extern "C" __global__
   void layernorm_reduce_rows_kernel(const float* __restrict__ x,
                                     long n_rows,
                                     long row_size,
                                     long blocks_per_row,
                                     double* __restrict__ sums,
                                     double* __restrict__ sumsq) {
       long row = blockIdx.x;
       long tile = blockIdx.y;
       if (row >= n_rows) return;
       long start = row * row_size;
       long tile_elems = (row_size + blocks_per_row - 1) / blocks_per_row;
       long tile_start = tile * tile_elems;
       if (tile_start >= row_size) return;
       long tile_end = ((tile_start + tile_elems) < row_size) ? (tile_start + tile_elems) : row_size;
         extern __shared__ double smem[]; // using 3*nwarps doubles: mean, m2, count
         double* s_mean = smem;
         double* s_m2 = smem + ((blockDim.x + 31) >> 5);
         double* s_count = smem + 2 * ((blockDim.x + 31) >> 5);
         double local_mean = 0.0;
         double local_M2 = 0.0;
         double local_count = 0.0;
         const float* x_row = x + start;
         long first_aligned = (tile_start + 3L) & ~3L; // ceil to multiple of 4
         if (first_aligned > tile_end) first_aligned = tile_end;
         // Prologue: scalar until alignment (Welford updates)
         for (long idx = tile_start + threadIdx.x; idx < first_aligned; idx += blockDim.x) {
             float v = x_row[idx];
             double xk = (double)v;
             local_count += 1.0;
             double delta = xk - local_mean;
             local_mean += delta / local_count;
             double delta2 = xk - local_mean;
             local_M2 += delta * delta2;
         }
         // Main: vectorized float4 with Welford updates
         long vec_elems = tile_end - first_aligned;
         long vec_chunks = vec_elems >> 2; // /4
         if (vec_chunks > 0) {
             const float4* __restrict__ x4 = reinterpret_cast<const float4*>(x_row + first_aligned);
             for (long c = threadIdx.x; c < vec_chunks; c += blockDim.x) {
                 float4 v4 = x4[c];
                 { double xk = (double)v4.x; local_count += 1.0; double d = xk - local_mean; local_mean += d / local_count; double d2 = xk - local_mean; local_M2 += d * d2; }
                 { double xk = (double)v4.y; local_count += 1.0; double d = xk - local_mean; local_mean += d / local_count; double d2 = xk - local_mean; local_M2 += d * d2; }
                 { double xk = (double)v4.z; local_count += 1.0; double d = xk - local_mean; local_mean += d / local_count; double d2 = xk - local_mean; local_M2 += d * d2; }
                 { double xk = (double)v4.w; local_count += 1.0; double d = xk - local_mean; local_mean += d / local_count; double d2 = xk - local_mean; local_M2 += d * d2; }
             }
         }
         // Epilogue: scalar tail (Welford updates)
         long last_aligned = first_aligned + (vec_chunks << 2);
         for (long idx = last_aligned + threadIdx.x; idx < tile_end; idx += blockDim.x) {
             float v = x_row[idx];
             double xk = (double)v;
             local_count += 1.0;
             double delta = xk - local_mean;
             local_mean += delta / local_count;
             double delta2 = xk - local_mean;
             local_M2 += delta * delta2;
         }
         // Warp-level Welford reduction then cross-warp finalize
         unsigned mask = 0xffffffffu; int lane = threadIdx.x & 31; int warp_id = threadIdx.x >> 5;
         for (int offset = 16; offset > 0; offset >>= 1) {
             double mean_b = __shfl_down_sync(mask, local_mean, offset);
             double m2_b   = __shfl_down_sync(mask, local_M2, offset);
             double cnt_b  = __shfl_down_sync(mask, local_count, offset);
             if (cnt_b > 0.0) {
                 double delta = mean_b - local_mean;
                 double tot = local_count + cnt_b;
                 local_mean += delta * (cnt_b / tot);
                 local_M2 += m2_b + delta * delta * (local_count * cnt_b / tot);
                 local_count = tot;
             }
         }
         if (lane == 0) { s_mean[warp_id] = local_mean; s_m2[warp_id] = local_M2; s_count[warp_id] = local_count; }
         __syncthreads();
         int nwarps = (blockDim.x + 31) >> 5;
         if (warp_id == 0) {
             double mean = (lane < nwarps) ? s_mean[lane] : 0.0;
             double m2   = (lane < nwarps) ? s_m2[lane]   : 0.0;
             double cnt  = (lane < nwarps) ? s_count[lane]: 0.0;
             for (int offset = 16; offset > 0; offset >>= 1) {
                 double mean_b = __shfl_down_sync(mask, mean, offset);
                 double m2_b   = __shfl_down_sync(mask, m2, offset);
                 double cnt_b  = __shfl_down_sync(mask, cnt, offset);
                 if (cnt_b > 0.0) {
                     double delta = mean_b - mean;
                     double tot = cnt + cnt_b;
                     mean += delta * (cnt_b / tot);
                     m2 += m2_b + delta * delta * (cnt * cnt_b / tot);
                     cnt = tot;
                 }
             }
             if (lane == 0) {
                 double sum = mean * cnt;
                 double sumsq_val = m2 + cnt * mean * mean;
                 atomicAdd(&sums[row], sum);
                 atomicAdd(&sumsq[row], sumsq_val);
             }
         }
    }
   extern "C" __global__
   void layernorm_apply_kernel(const float* __restrict__ x,
                               const float* __restrict__ gamma,
                               const float* __restrict__ beta,
                               float* __restrict__ y,
                               long n_rows,
                               long row_size,
                               long blocks_per_row,
                               double eps,
                               const double* __restrict__ sums,
                               const double* __restrict__ sumsq) {
      long row = blockIdx.x;
      long tile = blockIdx.y;
      if (row >= n_rows) return;
      long start = row * row_size;
      long tile_elems = (row_size + blocks_per_row - 1) / blocks_per_row;
      long tile_start = tile * tile_elems;
      if (tile_start >= row_size) return;
      long tile_end = ((tile_start + tile_elems) < row_size) ? (tile_start + tile_elems) : row_size;
      double mean = sums[row] / (double)row_size;
      double ex2 = sumsq[row] / (double)row_size;
      double var = ex2 - mean * mean;
      if (var < 0.0) var = 0.0;
      double inv_std = rsqrt(var + eps);
      const float* x_row = x + start;
      float* y_row = y + start;
      long first_aligned = (tile_start + 3L) & ~3L; // ceil to multiple of 4
      if (first_aligned > tile_end) first_aligned = tile_end;
      // Precompute constants when possible
      const bool has_gamma = (gamma != nullptr);
      const bool has_beta  = (beta  != nullptr);
      // Prologue: scalar until alignment
      for (long idx = tile_start + threadIdx.x; idx < first_aligned; idx += blockDim.x) {
          float v = x_row[idx];
          double vd = (double)v;
          float outv;
          if (has_gamma && has_beta) {
              double gg = (double)gamma[idx];
              double sc = gg * inv_std;
              double sh = (double)beta[idx] - mean * sc;
              outv = (float)(vd * sc + sh);
          } else if (has_gamma) {
              double gg = (double)gamma[idx];
              double sc = gg * inv_std;
              double sh = -mean * sc;
              outv = (float)(vd * sc + sh);
          } else if (has_beta) {
              double sc = inv_std;
              double sh = (double)beta[idx] - mean * sc;
              outv = (float)(vd * sc + sh);
          } else {
              double sc = inv_std;
              double sh = -mean * sc;
              outv = (float)(vd * sc + sh);
          }
          y_row[idx] = outv;
      }
      // Main: vectorized float4
      long vec_elems = tile_end - first_aligned;
      long vec_chunks = vec_elems >> 2; // /4
      if (vec_chunks > 0) {
          const float4* __restrict__ x4 = reinterpret_cast<const float4*>(x_row + first_aligned);
          float4* __restrict__ y4 = reinterpret_cast<float4*>(y_row + first_aligned);
          const float4* __restrict__ g4 = has_gamma ? reinterpret_cast<const float4*>(gamma + first_aligned) : nullptr;
          const float4* __restrict__ b4 = has_beta  ? reinterpret_cast<const float4*>(beta  + first_aligned) : nullptr;
          for (long c = threadIdx.x; c < vec_chunks; c += blockDim.x) {
              float4 vx = x4[c];
              float4 out;
              if (g4 != nullptr && b4 != nullptr) {
                  float4 gg = g4[c];
                  float4 bb = b4[c];
                  {
                      double sc = (double)gg.x * inv_std; double sh = (double)bb.x - mean * sc; out.x = (float)(((double)vx.x) * sc + sh);
                  }
                  {
                      double sc = (double)gg.y * inv_std; double sh = (double)bb.y - mean * sc; out.y = (float)(((double)vx.y) * sc + sh);
                  }
                  {
                      double sc = (double)gg.z * inv_std; double sh = (double)bb.z - mean * sc; out.z = (float)(((double)vx.z) * sc + sh);
                  }
                  {
                      double sc = (double)gg.w * inv_std; double sh = (double)bb.w - mean * sc; out.w = (float)(((double)vx.w) * sc + sh);
                  }
              } else if (g4 != nullptr) {
                  float4 gg = g4[c];
                  {
                      double sc = (double)gg.x * inv_std; double sh = -mean * sc; out.x = (float)(((double)vx.x) * sc + sh);
                  }
                  {
                      double sc = (double)gg.y * inv_std; double sh = -mean * sc; out.y = (float)(((double)vx.y) * sc + sh);
                  }
                  {
                      double sc = (double)gg.z * inv_std; double sh = -mean * sc; out.z = (float)(((double)vx.z) * sc + sh);
                  }
                  {
                      double sc = (double)gg.w * inv_std; double sh = -mean * sc; out.w = (float)(((double)vx.w) * sc + sh);
                  }
              } else if (b4 != nullptr) {
                  float4 bb = b4[c];
                  double sc = inv_std;
                  double shx = (double)bb.x - mean * sc; out.x = (float)(((double)vx.x) * sc + shx);
                  double shy = (double)bb.y - mean * sc; out.y = (float)(((double)vx.y) * sc + shy);
                  double shz = (double)bb.z - mean * sc; out.z = (float)(((double)vx.z) * sc + shz);
                  double shw = (double)bb.w - mean * sc; out.w = (float)(((double)vx.w) * sc + shw);
              } else {
                  double sc = inv_std;
                  double sh = -mean * sc;
                  out.x = (float)(((double)vx.x) * sc + sh);
                  out.y = (float)(((double)vx.y) * sc + sh);
                  out.z = (float)(((double)vx.z) * sc + sh);
                  out.w = (float)(((double)vx.w) * sc + sh);
              }
              y4[c] = out;
          }
      }
      // Epilogue: scalar tail
      long last_aligned = first_aligned + (vec_chunks << 2);
      for (long idx = last_aligned + threadIdx.x; idx < tile_end; idx += blockDim.x) {
          float v = x_row[idx];
          double vd = (double)v;
          float outv;
          if (has_gamma && has_beta) {
              double gg = (double)gamma[idx];
              double sc = gg * inv_std;
              double sh = (double)beta[idx] - mean * sc;
              outv = (float)(vd * sc + sh);
          } else if (has_gamma) {
              double gg = (double)gamma[idx];
              double sc = gg * inv_std;
              double sh = -mean * sc;
              outv = (float)(vd * sc + sh);
          } else if (has_beta) {
              double sc = inv_std;
              double sh = (double)beta[idx] - mean * sc;
              outv = (float)(vd * sc + sh);
          } else {
              double sc = inv_std;
              double sh = -mean * sc;
              outv = (float)(vd * sc + sh);
          }
          y_row[idx] = outv;
      }
   }
   torch::Tensor layernorm_forward(torch::Tensor x,
                                   c10::optional<torch::Tensor> gamma_opt,
                                   c10::optional<torch::Tensor> beta_opt,
                                   int64_t n_rows,
                                   int64_t row_size,
                                   double eps) {
       TORCH_CHECK(x.is_cuda(), "Input x must be on CUDA");
       TORCH_CHECK(x.scalar_type() == at::kFloat, "Only float32 is supported");
       auto x_contig = x.contiguous();
       const float* gamma_ptr = nullptr;
       const float* beta_ptr = nullptr;
       torch::Tensor gamma, beta;
       if (gamma_opt.has_value()) {
           gamma = gamma_opt.value();
           TORCH_CHECK(gamma.is_cuda(), "gamma must be on CUDA");
           TORCH_CHECK(gamma.scalar_type() == at::kFloat, "gamma must be float32");
           TORCH_CHECK(gamma.numel() == row_size, "gamma numel must equal row_size");
           gamma_ptr = gamma.contiguous().data_ptr<float>();
       }
       if (beta_opt.has_value()) {
           beta = beta_opt.value();
           TORCH_CHECK(beta.is_cuda(), "beta must be on CUDA");
           TORCH_CHECK(beta.scalar_type() == at::kFloat, "beta must be float32");
           TORCH_CHECK(beta.numel() == row_size, "beta numel must equal row_size");
           beta_ptr = beta.contiguous().data_ptr<float>();
       }
       TORCH_CHECK(x_contig.numel() == n_rows * row_size, "x.numel() must equal n_rows * row_size");
       auto y = torch::empty_like(x_contig);
        int threads = 256;
        dim3 block(threads);
         // Adaptive tiling: choose blocks_per_row to create enough total blocks across SMs
         int sm_count = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
         int64_t target_total_blocks = (int64_t)sm_count * 8; // aim for ~8 waves
         int64_t min_blocks_per_row = (target_total_blocks + n_rows - 1) / n_rows;
         if (min_blocks_per_row < 1) min_blocks_per_row = 1;
         if (min_blocks_per_row > 65535) min_blocks_per_row = 65535;
         int64_t blocks_per_row = min_blocks_per_row;
         int64_t tile_elems = (row_size + blocks_per_row - 1) / blocks_per_row;
         // Round tile size up to improve coalescing; keep a reasonable minimum
         const int64_t align = 256;
         tile_elems = ((tile_elems + align - 1) / align) * align;
         if (tile_elems < 256) tile_elems = 256;
         // Recompute blocks per row after alignment and clamp
         blocks_per_row = (row_size + tile_elems - 1) / tile_elems;
         if (blocks_per_row < 1) blocks_per_row = 1;
         if (blocks_per_row > 65535) blocks_per_row = 65535;
        dim3 grid_reduce((unsigned int)n_rows, (unsigned int)blocks_per_row, 1);
        size_t shmem = 3 * ((threads + 31) >> 5) * sizeof(double);
        // Workspace for per-row sums
        auto options = torch::TensorOptions().dtype(torch::kFloat64).device(x.device());
        auto sums = torch::zeros({n_rows}, options);
        auto sumsq = torch::zeros({n_rows}, options);
        const float* x_ptr = x_contig.data_ptr<float>();
        float* y_ptr = y.data_ptr<float>();
        double* sums_ptr = sums.data_ptr<double>();
        double* sumsq_ptr = sumsq.data_ptr<double>();
        cudaStream_t stream = at::cuda::getCurrentCUDAStream().stream();
        layernorm_reduce_rows_kernel<<<grid_reduce, block, shmem, stream>>>(
            x_ptr,
            (long)n_rows,
            (long)row_size,
            (long)blocks_per_row,
            sums_ptr,
            sumsq_ptr
        );
        auto err = cudaGetLastError();
        TORCH_CHECK(err == cudaSuccess, "CUDA kernel launch failed (reduce): ", cudaGetErrorString(err));
        dim3 grid_apply((unsigned int)n_rows, (unsigned int)blocks_per_row, 1);
        size_t shmem_apply = 0;
        layernorm_apply_kernel<<<grid_apply, block, shmem_apply, stream>>>(
            x_ptr,
            gamma_ptr,
            beta_ptr,
            y_ptr,
            (long)n_rows,
            (long)row_size,
            (long)blocks_per_row,
            eps,
            (const double*)sums_ptr,
            (const double*)sumsq_ptr
        );
        err = cudaGetLastError();
        TORCH_CHECK(err == cudaSuccess, "CUDA kernel launch failed (apply): ", cudaGetErrorString(err));
        return y;
   }
   """

_layernorm_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor layernorm_forward(torch::Tensor x,
                                c10::optional<torch::Tensor> gamma_opt,
                                c10::optional<torch::Tensor> beta_opt,
                                int64_t n_rows,
                                int64_t row_size,
                                double eps);
"""
_layernorm_ext = load_inline(
    name="layernorm_cuda_ext",
    cpp_sources=[_layernorm_cpp_decl],
    cuda_sources=[_layernorm_cuda_src],
    functions=["layernorm_forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, normalized_shape: tuple, eps: float = 1e-5, elementwise_affine: bool = True) -> None:
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = float(eps)
        self.elementwise_affine = elementwise_affine
        if self.elementwise_affine:
            self.weight = nn.Parameter(torch.ones(self.normalized_shape, dtype=torch.float32))
            self.bias = nn.Parameter(torch.zeros(self.normalized_shape, dtype=torch.float32))
        else:
            self.register_parameter("weight", None)
            self.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA"
        x = x.contiguous()
        # Compute row_size as product of normalized_shape, n_rows as remaining
        row_size = 1
        for d in self.normalized_shape:
            row_size *= int(d)
        total = x.numel()
        assert total % row_size == 0, "Input shape is incompatible with normalized_shape"
        n_rows = total // row_size

        gamma = None
        beta = None
        if self.elementwise_affine:
            # Ensure parameters are on same device and dtype
            assert self.weight.numel() == row_size, "Weight shape mismatch with normalized_shape"
            assert self.bias.numel() == row_size, "Bias shape mismatch with normalized_shape"
            if self.weight.device != x.device:
                gamma = self.weight.to(device=x.device, dtype=torch.float32)
            else:
                gamma = self.weight
            if self.bias.device != x.device:
                beta = self.bias.to(device=x.device, dtype=torch.float32)
            else:
                beta = self.bias

        # Enforce dtype float32 for kernel
        if x.dtype != torch.float32:
            x_in = x.to(dtype=torch.float32)
        else:
            x_in = x

        y = _layernorm_ext.layernorm_forward(x_in, gamma, beta, int(n_rows), int(row_size), float(self.eps))

        # Cast back to original dtype if needed
        if y.dtype != x.dtype:
            y = y.to(dtype=x.dtype)
        # Reshape is same as input since we operated in-place layout-preserving
        return y

batch_size = 16
features = 64
dim1 = 256
dim2 = 256

def get_inputs():
    x = torch.randn(batch_size, features, dim1, dim2, device="cuda")
    mean = 1000
    std_dev = 0.1
    x = x * std_dev + mean
    return [x]

def get_init_inputs():
    return [(features, dim1, dim2)]

